css:
#tongsci1-3-3-4-cover .frame { flex-direction: row; gap: 72px; }
#tongsci1-3-3-4-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci1-3-3-4-cover h1 { font-size: 112px; }
#tongsci1-3-3-4-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci1-3-3-4-cover .footer { left: 1100px; right: 300px; }
#tongsci1-3-3-4-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci1-3-3-4-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci1-3-3-4-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci1-3-3-4-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci1-3-3-4-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci1-3-3-4-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci1-3-3-4-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci1-3-3-4-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci1-3-3-4-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci1-3-3-4-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci1-3-3-4-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci1-3-3-4-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }
#tongsci1-3-3-4-cover .in-stage { height: 440px; border-radius: 8px; background: #2a3142; }
#tongsci1-3-3-4-cover .in-stage canvas { touch-action: none; cursor: grab; }
#tongsci1-3-3-4-cover .in-stage canvas.holding { cursor: grabbing; }
#tongsci1-3-3-4-cover .in-stage .now-chip { top: 8px; left: 10px; max-width: 64%; width: fit-content; font-size: 16px; line-height: 1.3; padding: 5px 12px; }
#tongsci1-3-3-4-cover .in-stage .now-chip b { color: #7a1f12; }
#tongsci1-3-3-4-cover .in-card .share-opts { grid-template-columns: 1fr 1.9fr 1fr; }
#tongsci1-3-3-4-cover .in-card .share-opts button { font-size: 19px; padding: 10px 8px; line-height: 1.25; }
#tongsci1-3-3-4-cover:has(.in-card) .footer { left: 560px; }

js:
/* tongsci1.3-3.4.cover */
(function () {
  'use strict';
  const { part } = window.Deck;
  const J = (m, root) => window.EthTrack.join(m, window.L1.frame(root));
  part('tongsci1-3-3-4-cover', (root) => {
    const st = window.Insulin.mount(root), fr = window.L1.frame(root), btns = [...root.querySelectorAll('.share-opts button')];
    btns.forEach((b) => b.addEventListener('click', () => { const on = b.getAttribute('aria-pressed') !== 'true'; btns.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b))); }));
    const answer = (on) => root.querySelector('#pr-b').classList.toggle('answer', on);
    return { fit: st.fit, setActive(on) { st.setActive(on); fr.setActive(on); }, fragment(f, on) { if (f.dataset.anim === 'is') answer(on); }, sync(slide) { const f = slide.querySelector('[data-anim="is"]'); answer(!!f && f.classList.contains('visible')); } };
  });
})();
